  text-align: center;
  width: 20%;
}

.id {
  font-size: 8px;
  color: #333;
  margin-bottom: 4px;
}

.info {
  font-size: 8px;
  color: #4a89dc;
  background: #f8f9fa;
  padding: 2px 5px;
  border-radius: 10px;
}

/* 章节介绍区域 */
.chapter-intro {
  flex: 1;
  min-width: 0; /* 重要：允许内容收缩 */
  width:70%
}


.chapter,.chapter>div {
  font-size: 12px;
  color: #333;
  font-weight: 500;
  margin-bottom: 5px;
  white-space: nowrap;
  width:100%;
}



.intro {
  font-size: 10px;
  color: #6c757d;
  display: flex;
  align-items: center;
  overflow:hidden;
  width:100%;
  display: -webkit-box; 
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2; 
}

.intro span {
  color: #ff3852;
  font-weight: 600;
  margin: 0 2px;
}

.date,.date>div {
  font-size: 12px;
  color: #333;
  font-weight: 500;
  margin-bottom: 5px;
  white-space: nowrap;
  position: relative;
  width:100%;
}

.date,.chapter{
    overflow: hidden;
}

@keyframes marquee {
  0% {
    transform: translateX(20px);
  }
  100% {
    transform: translateX(-100%);
  }
}


.scrollable {
  display: inline-block;
  white-space: nowrap;
  animation: marquee 5s linear infinite;
  animation-play-state: running;
}

.date-intro .intro {
  font-size: 12px;
  color: #6c757d;
  white-space: nowrap;

}

